import{_ as t,o as e,c as d,ag as n}from"./chunks/framework.Dx86EdC1.js";const m=JSON.parse('{"title":"PPID Desa","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/ppid.md","filePath":"panduan-pengguna/ppid.md","lastUpdated":1791382762000}'),r={name:"panduan-pengguna/ppid.md"};function o(i,a,s,u,l,p){return e(),d("div",null,[...a[0]||(a[0]=[n('<h1 id="ppid-desa" tabindex="-1">PPID Desa <a class="header-anchor" href="#ppid-desa" aria-label="Permalink to &quot;PPID Desa&quot;">​</a></h1><p>Layanan <strong>Pejabat Pengelola Informasi dan Dokumentasi (PPID)</strong> mengimplementasikan standar keterbukaan informasi publik sesuai <strong>UU No. 14/2008</strong> dan <strong>Perki No. 1/2018</strong>.</p><h2 id="struktur-ppid" tabindex="-1">Struktur PPID <a class="header-anchor" href="#struktur-ppid" aria-label="Permalink to &quot;Struktur PPID&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Jabatan</th><th>Diisi oleh</th></tr></thead><tbody><tr><td>Atasan PPID</td><td>Kepala Desa</td></tr><tr><td>PPID Desa</td><td>Sekretaris Desa</td></tr><tr><td>Petugas Pelayanan Informasi</td><td>Perangkat Desa</td></tr></tbody></table><p>Diatur di <strong>PPID → Pengaturan</strong> (<code>/admin/ppid-settings</code>).</p><h2 id="dokumen-publik-admin-ppid-documents" tabindex="-1">Dokumen Publik (<code>/admin/ppid-documents</code>) <a class="header-anchor" href="#dokumen-publik-admin-ppid-documents" aria-label="Permalink to &quot;Dokumen Publik (`/admin/ppid-documents`)&quot;">​</a></h2><p>Kelola Daftar Informasi Publik (DIP) dengan klasifikasi baku:</p><table tabindex="0"><thead><tr><th>Kategori</th><th>Label</th></tr></thead><tbody><tr><td><code>berkala</code></td><td>Informasi Berkala</td></tr><tr><td><code>setiap_saat</code></td><td>Informasi Setiap Saat</td></tr><tr><td><code>serta_merta</code></td><td>Informasi Serta Merta</td></tr><tr><td><code>dikecualikan</code></td><td>Informasi Dikecualikan</td></tr></tbody></table><p>Dokumen bawaan: RKPDes, LPPD, realisasi APBDes, Perdes, SOP layanan, surat edaran darurat, dll. Field: judul, jenis, tahun, deskripsi, berkas (PDF), status terbit, jumlah unduhan.</p><h3 id="harmonisasi-kip-pdp" tabindex="-1">Harmonisasi KIP &amp; PDP <a class="header-anchor" href="#harmonisasi-kip-pdp" aria-label="Permalink to &quot;Harmonisasi KIP &amp; PDP&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Wajib</p><p>Dokumen yang memuat <strong>data pribadi warga</strong> (NIK, No KK, riwayat medis) <strong>wajib disamarkan/dikecualikan</strong> sebelum dipublikasikan ke DIP — prinsip UU PDP No. 27/2022. Gunakan kategori <code>dikecualikan</code> untuk dokumen yang tidak boleh dibuka publik.</p></div><h2 id="permohonan-informasi-publik" tabindex="-1">Permohonan Informasi (Publik) <a class="header-anchor" href="#permohonan-informasi-publik" aria-label="Permalink to &quot;Permohonan Informasi (Publik)&quot;">​</a></h2><p>Warga mengajukan di <strong><code>/ppid/permohonan</code></strong>. Penomoran tiket otomatis:</p><ul><li>Permohonan: <code>INF-YYYYMMDD-XXXX</code></li><li>Keberatan: <code>KBR-YYYYMMDD-XXXX</code></li></ul><p>Status permohonan (<code>InformationRequest</code>):</p><table tabindex="0"><thead><tr><th>Status</th><th>Label</th></tr></thead><tbody><tr><td><code>submitted</code></td><td>Menunggu Verifikasi</td></tr><tr><td><code>processed</code></td><td>Sedang Diproses PPID</td></tr><tr><td><code>approved</code></td><td>Disetujui / Selesai</td></tr><tr><td><code>rejected</code></td><td>Ditolak</td></tr></tbody></table><h3 id="tracking-keberatan" tabindex="-1">Tracking &amp; Keberatan <a class="header-anchor" href="#tracking-keberatan" aria-label="Permalink to &quot;Tracking &amp; Keberatan&quot;">​</a></h3><ul><li>Cek status via <strong><code>/ppid/tracking</code></strong> dengan nomor tiket.</li><li>Jika permohonan ditolak atau belum dijawab sampai batas waktu, warga dapat mengajukan <strong>keberatan</strong> di <code>/ppid/keberatan/{ticket}</code> (tiket <code>KBR-...</code>).</li></ul><h2 id="proses-di-dashboard-admin" tabindex="-1">Proses di Dashboard Admin <a class="header-anchor" href="#proses-di-dashboard-admin" aria-label="Permalink to &quot;Proses di Dashboard Admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>Aksi</th></tr></thead><tbody><tr><td><strong>PPID → Permohonan</strong> (<code>/admin/ppid-requests</code>)</td><td>Proses, setujui, atau tolak permohonan (dengan alasan)</td></tr><tr><td><strong>PPID → Keberatan</strong> (<code>/admin/ppid-objections</code>)</td><td>Tanggapi keberatan</td></tr><tr><td><strong>PPID → Dokumen</strong></td><td>Kelola DIP &amp; unduhan berkas</td></tr><tr><td><strong>PPID → Pengaturan</strong></td><td>Profil pejabat, maklumat pelayanan</td></tr></tbody></table><h2 id="unduhan-dokumen-publik" tabindex="-1">Unduhan Dokumen Publik <a class="header-anchor" href="#unduhan-dokumen-publik" aria-label="Permalink to &quot;Unduhan Dokumen Publik&quot;">​</a></h2><p>Publik mengunduh di <strong><code>/ppid/dokumen</code></strong> → <code>/ppid/dokumen/{id}/download</code>. Jumlah unduhan tercatat per dokumen.</p>',22)])])}const c=t(r,[["render",o]]);export{m as __pageData,c as default};
